package com.smartdairy.controller;
import com.smartdairy.entity.MilkCollection; import com.smartdairy.service.MilkCollectionService; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.time.LocalDate;
public class MilkCollectionServlet extends HttpServlet {private final MilkCollectionService service=new MilkCollectionService(); protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{MilkCollection m=new MilkCollection();m.setCollectionDate(LocalDate.parse(req.getParameter("collection_date")));m.setSupplierName(req.getParameter("supplier_name"));m.setShift(req.getParameter("shift"));m.setAnimalType(req.getParameter("animal_type"));m.setQuantity(Double.parseDouble(req.getParameter("quantity")));m.setFat(parse(req.getParameter("fat")));m.setSnf(parse(req.getParameter("snf")));m.setRate(Double.parseDouble(req.getParameter("rate")));service.create(m);resp.sendRedirect("milk_collection.jsp?success=true");}catch(Exception e){resp.sendRedirect("milk_collection.jsp?error="+java.net.URLEncoder.encode(e.getMessage(),"UTF-8"));}} private double parse(String s){return s==null||s.trim().isEmpty()?0:Double.parseDouble(s);}}
